export default function Corrections() {
  const exchange = session.lastExchange;
  const [kept, setKept] = useState<string[] | null>(null);

  if (kept) return <ExchangeDone phrases={kept} />;

  const corrections = exchange?.corrections ?? [];
  const keptPhrases = exchange?.kept_phrase_fr ?? [];

  function keepAll() {
    const place = session.scene?.place;
    const crop = session.frame ?? undefined;
    for (const c of corrections) {
      store.keep({ phrase_fr: c.better, phrase_en: c.why_en, noun_fr: c.better, errorType: c.type, place, crop });
    }
    for (const phrase_fr of keptPhrases) {
      store.keep({ phrase_fr, phrase_en: "", place, crop });
    }
    setKept([...new Set([...corrections.map((c) => c.better), ...keptPhrases])]);
  }

  return (
    <section className="flex min-h-screen flex-col gap-4 p-4">
      {corrections.length === 0 ? (
        <div className="flex flex-col gap-2 rounded-[var(--radius-m)] bg-card p-4 shadow">
          <p>nothing to fix, nice</p>
          {keptPhrases.map((p) => (
            <p key={p} className="text-[length:var(--text-l)]">
              {p}
            </p>
          ))}
        </div>
      ) : (
        <ul className="flex flex-col gap-3">
          {corrections.map((c) => (
            <CorrectionCard key={`${c.said}|${c.better}`} c={c} />
          ))}
        </ul>
      )}
      <button
        type="button"
        onClick={keepAll}
        className="rounded-[var(--radius-pill)] bg-accent px-5 py-2 text-card"
      >
        keep both and continue
      </button>
    </section>
  );
}
import { useState, type FormEvent } from "react";
import { postCheck } from "../lib/api";
import { getSettings } from "../lib/settings";
import type { Card } from "../lib/types";
import { gradeFromTranscript } from "../srs/recall";
import * as store from "../srs/store";
import { useVoice } from "../voice/useVoice";

type Group = { key: string; cards: Card[] };

function groupDue(cards: Card[]): Group[] {
  const map = new Map<string, Card[]>();
  for (const c of cards) {
    const key = c.errorType ?? "phrase";
    map.set(key, [...(map.get(key) ?? []), c]);
  }
  return [...map].map(([key, cards]) => ({ key, cards }));
}

function summary(group: Group): string {
  if (group.key === "article") return "you keep dropping the article on feminine nouns";
  if (group.key === "gender") return "you keep mixing up le and la";
  return `${group.cards.length} to say again`;
}

function days(n: number): string {
  return `${n} ${n === 1 ? "day" : "days"}`;
}

async function gradeAttempt(transcript: string, target: string): Promise<number> {
  try {
    const res = await postCheck({ target_fr: target, transcript, level: getSettings().level });
    return res.grade;
  } catch {
    return gradeFromTranscript(transcript, target);
  }
}

interface Result {
  q: number;
  interval: number;
  said: string;
}

function ReviewCard({ card, position, total, onNext }: { card: Card; position: number; total: number; onNext: () => void }) {
  const [result, setResult] = useState<Result | null>(null);
  const [typed, setTyped] = useState("");
  const [busy, setBusy] = useState(false);

  async function attempt(transcript: string) {
    if (busy || result) return;
    setBusy(true);
    const q = await gradeAttempt(transcript, card.phrase_fr);
    const graded = store.grade(card.id, q);
    setResult({ q, interval: graded.interval, said: transcript });
    setBusy(false);
  }

  // Automocked in tests, so the hook may return undefined.
  const voice = useVoice({ onFinal: (text) => void attempt(text) }) as ReturnType<typeof useVoice> | undefined;

  function submit(e: FormEvent) {
    e.preventDefault();
    void attempt(typed);
  }

  return (
    <section className="flex flex-col gap-4 p-[var(--gutter)]">
      <p className="text-[length:var(--text-micro)] text-muted">
        {position} of {total}
      </p>
      {card.crop ? (
        <img src={card.crop} alt={card.place ?? card.phrase_en} className="w-full rounded-[var(--radius-card)] object-cover" />
      ) : (
        card.place && <p className="text-[length:var(--text-small)] text-muted">your {card.place}</p>
      )}
      <p className="text-[length:var(--text-title)] leading-[var(--lh-title)]">say it: {card.phrase_en}</p>

      {result ? (
        <div className="flex flex-col gap-3">
          <p className={result.q >= 3 ? "text-[var(--moss)]" : "text-[var(--clay)]"}>
            {result.q >= 3 ? `good, next in ${days(result.interval)}` : "not yet, again tomorrow"}
          </p>
          <p className="text-[length:var(--text-title)]">{card.phrase_fr}</p>
          {result.said && <p className="text-[length:var(--text-small)] text-muted">you: {result.said}</p>}
          <button
            type="button"
            onClick={onNext}
            className="rounded-[var(--radius-button)] bg-accent px-5 py-3 text-card"
          >
            next
          </button>
        </div>
      ) : (
        <>
          <button
            type="button"
            disabled={busy}
            onPointerDown={() => void voice?.startListening()}
            onPointerUp={() => voice?.stopListening()}
            onPointerLeave={() => voice?.stopListening()}
            className="self-center rounded-[var(--radius-pill)] bg-accent px-6 py-4 text-card"
          >
            {voice?.state === "listening" ? "listening" : "hold to talk"}
          </button>
          {voice?.partial && <p className="text-center text-muted">{voice.partial}</p>}
          <form onSubmit={submit} className="flex gap-2">
            <label className="flex flex-1 flex-col gap-1 text-[length:var(--text-small)] text-muted">
              or type it
              <input
                value={typed}
                onChange={(e) => setTyped(e.target.value)}
                lang="fr"
                className="rounded-[var(--radius-button)] border border-line bg-card px-3 py-2 text-ink"
              />
            </label>
            <button
              type="submit"
              disabled={busy}
              className="self-end rounded-[var(--radius-button)] border border-line bg-card px-4 py-2"
            >
              check
            </button>
          </form>
        </>
      )}
    </section>
  );
}

export default function Review() {
  const [run, setRun] = useState<Card[] | null>(null);
  const [index, setIndex] = useState(0);

  if (run && index < run.length) {
    return (
      <ReviewCard
        key={run[index].id}
        card={run[index]}
        position={index + 1}
        total={run.length}
        onNext={() => {
          if (index + 1 < run.length) setIndex(index + 1);
          else {
            setRun(null);
            setIndex(0);
          }
        }}
      />
    );
  }

  const due = store.due();
  const groups = groupDue(due);

  function start(first: Card[] = []) {
    const ids = new Set(first.map((c) => c.id));
    setRun([...first, ...due.filter((c) => !ids.has(c.id))]);
    setIndex(0);
  }

  return (
    <section className="flex flex-col gap-4 p-[var(--gutter)]">
      <header>
        <h1 className="text-[length:var(--text-h1)] leading-[var(--lh-h1)]">review</h1>
        <p className="text-[length:var(--text-small)] text-muted">
          due now <span data-testid="due-count">{due.length}</span>
        </p>
      </header>

      {due.length === 0 ? (
        <p className="text-muted">nothing due, go look at something</p>
      ) : (
        <>
          {groups.map((g) => (
            <button
              key={g.key}
              type="button"
              data-group={g.key}
              onClick={() => start(g.cards)}
              className="flex flex-col gap-1 rounded-[var(--radius-card)] border border-line bg-card p-4 text-left"
            >
              <span className="text-[length:var(--text-title)]">
                {g.key} · {g.cards.length}
              </span>
              <span className="text-[length:var(--text-small)] text-muted">{summary(g)}</span>
            </button>
          ))}
          <button
            type="button"
            onClick={() => start()}
            className="rounded-[var(--radius-button)] bg-accent px-5 py-3 text-card"
          >
            start
          </button>
        </>
      )}
    </section>
  );
}
import { useState } from "react";
import type { Card, Conversation } from "../lib/types";
import * as conversations from "../srs/conversations";
import * as store from "../srs/store";

type Filter = "all" | "scenes" | "conversations";
const FILTERS: Filter[] = ["all", "scenes", "conversations"];
const WEEKDAYS = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];

type Entry = { kind: "scene"; at: number; card: Card } | { kind: "conversation"; at: number; conv: Conversation };

const pad = (n: number) => String(n).padStart(2, "0");

function isoDate(ms: number): string {
  const d = new Date(ms);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function weekdayTime(ms: number): string {
  const d = new Date(ms);
  return `${WEEKDAYS[d.getDay()]} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function WaveGlyph() {
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" aria-hidden>
      <path d="M3 12h2M7 8v8M11 5v14M15 9v6M19 11v2" />
    </svg>
  );
}

function ConversationRow({ conv }: { conv: Conversation }) {
  const [open, setOpen] = useState(false);
  const at = Date.parse(conv.startedAt);
  return (
    <li data-testid="diary-conversation" className="col-span-2 rounded-[var(--radius-card)] border border-line bg-card">
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-expanded={open}
        className="flex w-full items-center gap-3 p-3 text-left"
      >
        <span className="text-accent">
          <WaveGlyph />
        </span>
        <span className="flex flex-1 flex-col">
          <span className="text-[length:var(--text-body)] leading-[var(--lh-body)]">
            {conv.place ?? "conversation"}, {weekdayTime(at)}
          </span>
          <span className="text-[length:var(--text-small)] text-muted">
            {conv.lines.length} lines, {conv.keptCount} kept
          </span>
        </span>
        <time dateTime={isoDate(at)} className="text-[length:var(--text-micro)] text-muted">
          {isoDate(at)}
        </time>
      </button>
      {open && (
        <ol className="flex flex-col gap-2 border-t border-line p-3">
          {conv.lines.map((l, i) => (
            <li key={i}>
              <p className={l.kept ? "text-accent" : ""}>{l.fr}</p>
              <p className="text-[length:var(--text-small)] text-muted">{l.en}</p>
            </li>
          ))}
        </ol>
      )}
    </li>
  );
}

function SceneTile({ card }: { card: Card }) {
  return (
    <li data-testid="diary-tile" className="overflow-hidden rounded-[var(--radius-card)] border border-line bg-card">
      {card.crop ? (
        <img src={card.crop} alt={card.place ?? card.phrase_fr} className="aspect-square w-full object-cover" />
      ) : (
        <div aria-hidden className="aspect-square w-full bg-line" />
      )}
      <div className="flex flex-col gap-1 p-3">
        <p className="text-[length:var(--text-body)] leading-[var(--lh-body)]">{card.phrase_fr}</p>
        {card.place && <p className="text-[length:var(--text-small)] text-muted">{card.place}</p>}
        <time dateTime={isoDate(card.learnedAt)} className="text-[length:var(--text-micro)] text-muted">
          {isoDate(card.learnedAt)}
        </time>
      </div>
    </li>
  );
}

export default function Diary() {
  const [filter, setFilter] = useState<Filter>("all");
  const entries: Entry[] = [
    ...(filter === "conversations" ? [] : store.all().map((card): Entry => ({ kind: "scene", at: card.learnedAt, card }))),
    ...(filter === "scenes"
      ? []
      : conversations.all().map((conv): Entry => ({ kind: "conversation", at: Date.parse(conv.startedAt), conv }))),
  ].sort((a, b) => b.at - a.at);
  const empty = store.all().length === 0 && conversations.all().length === 0;

  return (
    <section className="flex flex-col gap-4 p-[var(--gutter)]">
      <h1 className="text-[length:var(--text-h1)] leading-[var(--lh-h1)]">what you can say now</h1>
      <div role="group" aria-label="filter" className="flex gap-2">
        {FILTERS.map((f) => (
          <button
            key={f}
            type="button"
            onClick={() => setFilter(f)}
            aria-pressed={filter === f}
            className={`rounded-[var(--radius-chip)] border px-3 py-1 text-[length:var(--text-small)] ${
              filter === f ? "border-accent bg-accent-soft text-accent" : "border-line bg-card text-muted"
            }`}
          >
            {f}
          </button>
        ))}
      </div>
      {empty ? (
        <p className="text-muted">nothing kept yet, go look at something</p>
      ) : (
        <ul className="grid grid-cols-2 gap-3">
          {entries.map((e) =>
            e.kind === "scene" ? <SceneTile key={e.card.id} card={e.card} /> : <ConversationRow key={e.conv.id} conv={e.conv} />,
          )}
        </ul>
      )}
    </section>
  );
}
import { useEffect, useState, useSyncExternalStore, type ChangeEvent } from "react";
import { getSettings, setSettings, type Settings as SettingsShape } from "../lib/settings";
import type { Level } from "../lib/types";
import * as store from "../srs/store";
import { gemma, MODEL_FILE, type GemmaStatus } from "../offline/gemma";
import { useInstallPrompt } from "../pwa/install";

const levels: Level[] = ["A1", "A2", "B1", "B2"];

const voices = [
  { id: "YKeBw3OV1RgpdhLh", name: "Jules" },
  { id: "biuhvu17TxVKOcyy", name: "Marius" },
  { id: "iEu63s1rhn_kegTr", name: "Gaspard" },
  { id: "YhIHaAfQ0cQPDV9R", name: "Solène" },
  { id: "FXxJ9mANRq6BCTX5", name: "Noémie" },
];

const modelUrl = (import.meta.env.VITE_GEMMA_MODEL_URL as string | undefined) || "";

function statusText(s: GemmaStatus): string {
  switch (s.state) {
    case "unavailable":
      return "not supported in this browser (needs webgpu)";
    case "absent":
      return "not installed";
    case "loading":
      return s.progress === undefined ? "loading" : `loading ${s.progress} %`;
    case "ready":
      return "ready";
    case "error":
      return s.reason ? `error: ${s.reason}` : "error";
  }
}

const row = "flex flex-col gap-2 rounded-[var(--radius-card)] border border-line bg-card p-4";
const control = "rounded-[var(--radius-button)] border border-line bg-card px-3 py-2";

export default function Settings() {
  const [settings, setLocal] = useState(getSettings);
  const [cleared, setCleared] = useState(false);

  function update(partial: Partial<SettingsShape>) {
    setLocal(setSettings(partial));
  }

  function clearAll() {
    if (!window.confirm("clear everything? this removes every kept phrase.")) return;
    store.clear();
    setCleared(true);
  }

  return (
    <section className="flex flex-col gap-3 p-[var(--gutter)]">
      <h1 className="text-[length:var(--text-h1)] leading-[var(--lh-h1)]">settings</h1>

      <div className={row}>
        <span className="text-muted">language</span>
        <span>french</span>
      </div>

      <label className={row}>
        <span className="text-muted">level</span>
        <select
          value={settings.level}
          onChange={(e) => update({ level: e.target.value as Level })}
          className={control}
        >
          {levels.map((l) => (
            <option key={l} value={l}>
              {l}
            </option>
          ))}
        </select>
      </label>

      <label className={row}>
        <span className="text-muted">voice</span>
        <select value={settings.voiceId} onChange={(e) => update({ voiceId: e.target.value })} className={control}>
          {voices.map((v) => (
            <option key={v.id} value={v.id}>
              {v.name}
            </option>
          ))}
        </select>
      </label>

      <label className={row}>
        <span className="text-muted">speed {settings.speed.toFixed(1)}</span>
        <input
          type="range"
          min={0.8}
          max={1.2}
          step={0.1}
          value={settings.speed}
          onChange={(e) => update({ speed: Number(e.target.value) })}
          className="accent-[var(--moss)]"
        />
      </label>

      <OnYourPhone />

      <OfflineTutor />

      <div className={row}>
        <span className="text-muted">data</span>
        <p className="text-[length:var(--text-small)] text-muted">everything stays in this browser</p>
        <button
          type="button"
          onClick={clearAll}
          className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 text-[var(--clay)]"
        >
          clear everything
        </button>
        {cleared && <p className="text-[length:var(--text-small)] text-muted">cleared</p>}
      </div>
    </section>
  );
}

function OnYourPhone() {
  const { canInstall, install, platform, installed } = useInstallPrompt();

  let body;
  if (installed) {
    body = <p>installed. works offline.</p>;
  } else if (canInstall) {
    body = (
      <button
        type="button"
        onClick={() => void install()}
        className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2"
      >
        add to home screen
      </button>
    );
  } else if (platform === "ios") {
    body = (
      <ol className="flex flex-col gap-1 text-[length:var(--text-small)]">
        <li>open in safari</li>
        <li>tap share</li>
        <li>add to home screen</li>
      </ol>
    );
  } else {
    body = <p className="text-[length:var(--text-small)] text-muted">open this page on your phone to install it</p>;
  }

  return (
    <div className={row} data-testid="on-your-phone">
      <span className="text-muted">on your phone</span>
      {body}
    </div>
  );
}

function OfflineTutor() {
  const status = useSyncExternalStore(gemma.subscribe, gemma.status);
  const [failed, setFailed] = useState<string | null>(null);

  useEffect(() => {
    void gemma.refresh();
  }, []);

  function run(job: Promise<void>) {
    setFailed(null);
    job.catch((e: unknown) => setFailed(e instanceof Error ? e.message : "could not install"));
  }

  function onFile(e: ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    e.target.value = "";
    if (file) run(gemma.importFile(file));
  }

  function remove() {
    if (!window.confirm("remove the offline tutor? you will need to pick the file again.")) return;
    run(gemma.remove());
  }

  const busy = status.state === "loading";
  const usable = status.state !== "unavailable";

  return (
    <div className={row}>
      <span className="text-muted">offline tutor</span>
      <p data-testid="offline-status">{statusText(status)}</p>
      {usable &&
        (modelUrl ? (
          <button
            type="button"
            disabled={busy}
            onClick={() => run(gemma.importUrl(modelUrl))}
            className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 disabled:opacity-50"
          >
            download
          </button>
        ) : (
          <label className="flex flex-col gap-1">
            <span className="text-[length:var(--text-small)]">choose {MODEL_FILE}</span>
            <input
              type="file"
              accept=".task"
              aria-label={`choose ${MODEL_FILE}`}
              disabled={busy}
              onChange={onFile}
              className={control}
            />
          </label>
        ))}
      {usable && (status.state === "ready" || status.state === "error") && (
        <button
          type="button"
          onClick={remove}
          className="self-start rounded-[var(--radius-pill)] border border-line px-4 py-2 text-[var(--clay)]"
        >
          remove
        </button>
      )}
      {failed && <p className="text-[length:var(--text-small)] text-muted">{failed}</p>}
      <p className="text-[length:var(--text-small)] text-muted">
        when the network is gone, noé runs on gemma 3 1b in this browser. get {MODEL_FILE} (about 700 mb) from{" "}
        <a
          href="https://huggingface.co/litert-community/Gemma3-1B-IT"
          target="_blank"
          rel="noreferrer"
          className="underline"
        >
          hugging face
        </a>
        . you accept the gemma licence there first. the file stays in this browser.
      </p>
    </div>
  );
}

