            : "bg-snow/60"
          : state === "thinking"
            ? "bg-ink/30"
            : "bg-ink/50";
  return (
    <span aria-hidden className="relative flex h-[104px] w-[104px] items-center justify-center">
      {state === "listening" && (
        <span className="absolute inset-0 rounded-[var(--radius-pill)] border border-moss opacity-20 motion-safe:animate-ping" />
